import { useState } from "react";
import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css";

export function Form({ onTaskCreation }) {
  const [taskName, setTaskName] = useState("");
  const [taskType, setTaskType] = useState("Other");
  const [taskDescription, setTaskDescription] = useState("");
  const [dueDate, setDueDate] = useState(null);
  const [taskStatus, setTaskStatus] = useState("Pending");
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState("");

  const submitEvent = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError("");
    const body = {
      task_name: taskName,
      task_type: taskType,
      task_description: taskDescription,
      task_status: taskStatus,
      due_date: dueDate ? dueDate.toISOString() : null,
    };
    try {
      const res = await fetch("/api/tasks", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
      if (res.ok) {
        setTaskName("");
        setTaskType("Other");
        setTaskDescription("");
        setDueDate(null);
        setTaskStatus("Pending");
        setError("");
        onTaskCreation();
      } else {
        const errText = await res.text();
        setError(`Error: ${errText}`);
        console.error("Create failed", errText);
      }
    } catch (err) {
      setError(`Network error: ${err.message}`);
      console.error("Network error", err);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <form className="form" onSubmit={submitEvent}>
      <label htmlFor="task_name">Task name</label>
      <input
        id="task_name"
        name="task_name"
        value={taskName}
        onChange={(e) => setTaskName(e.target.value)}
        required
      />

      <label htmlFor="task_type">Type</label>
      <select
        id="task_type"
        value={taskType}
        onChange={(e) => setTaskType(e.target.value)}
      >
        <option>Hearing</option>
        <option>Case Review</option>
        <option>Document Review</option>
        <option>Bug</option>
        <option>Other</option>
      </select>

      <label htmlFor="task_description">Description</label>
      <textarea
        id="task_description"
        value={taskDescription}
        onChange={(e) => setTaskDescription(e.target.value)}
      />

      <label htmlFor="task_status">Status</label>
      <select
        id="task_status"
        value={taskStatus}
        onChange={(e) => setTaskStatus(e.target.value)}
      >
        <option>Pending</option>
        <option>In Progress</option>
        <option>Resulsted</option>
        <option>Deleted</option>
      </select>

      <label htmlFor="due_date">Due Date</label>
      <DatePicker
        id="due_date"
        selected={dueDate}
        onChange={(date) => setDueDate(date)}
        dateFormat="yyyy-MM-dd"
        placeholderText="Select due date"
        isClearable
      />

      {error && (
        <div style={{ color: "red", marginBottom: "10px" }}>{error}</div>
      )}

      <button type="submit" disabled={isLoading}>
        {isLoading ? "Creating..." : "Create task"}
      </button>
    </form>
  );
}
